function drawNorth(page,x,y){page.line(x,y+12,x,y,'#111',.5);page.poly([[x,y],[x-2.2,y+5],[x+2.2,y+5]],'#111','#111',.3);page.text('N',x-1.5,y+17,8,true,'#111');}
function drawScaleBar(page,x,y,scale,maxW=45){const choices=[1,2,5,10,20,50,100,200,500,1000,2000];const metersPerMm=scale/1000;const m=choices.filter(v=>v/metersPerMm<=maxW).at(-1)||1,w=m/metersPerMm;page.line(x,y,x+w,y,'#111',.8);page.line(x,y-1.5,x,y+1.5,'#111',.4);page.line(x+w/2,y-1.5,x+w/2,y+1.5,'#111',.4);page.line(x+w,y-1.5,x+w,y+1.5,'#111',.4);page.text('0',x-1,y+5,5.2,false);page.text(String(m/2),x+w/2-2,y+5,5.2,false);page.text((m>=1000?(m/1000)+' km':m+' m'),x+w-3,y+5,5.2,false);}
