function titleBlock(page,project,opt,pageNo,total,scaleText='NTS'){const x=12,y=page.h-44,w=page.w-24,h=32;page.rect(x,y,w,h,'#24332f',null,.35);const c1=x+w*.20,c2=x+w*.42,c3=x+w*.63,c4=x+w*.82;const cols=[x,c1,c2,c3,c4,x+w];for(let i=1;i<cols.length-1;i++)page.line(cols[i],y,cols[i],y+h,'#73807c',.2);page.line(x,y+11,x+w,y+11,'#73807c',.2);const m=project.meta||{};const status=opt.status||m.drawingStatus||'Preliminary';page.text('PROJECT',x+2,y+4,4.5,true,'#52615d');page.text(project.name||'Untitled site',x+2,y+9,6.7,true);page.text('CLIENT',c1+2,y+4,4.5,true,'#52615d');page.text(m.clientName||'-',c1+2,y+9,6.2,true);page.text('DRAWING / REFERENCE',c2+2,y+4,4.5,true,'#52615d');page.text(m.drawingNo||m.siteRef||'SAMI-SITE',c2+2,y+9,6.2,true);page.text('REVISION',c3+2,y+4,4.5,true,'#52615d');page.text(opt.revision||m.revision||'-',c3+2,y+9,6.2,true);page.text('SCALE',c4+2,y+4,4.5,true,'#52615d');page.text(scaleText,c4+2,y+9,6.2,true);page.text('STATUS',x+2,y+16,4.5,true,'#52615d');page.text(status,x+2,y+22,6.0,true);page.text('PREPARED BY',c1+2,y+16,4.5,true,'#52615d');page.text(opt.preparedBy||m.creator||'-',c1+2,y+22,6.0,true);page.text('DATE',c2+2,y+16,4.5,true,'#52615d');page.text(new Date().toLocaleDateString('en-GB'),c2+2,y+22,6.0,true);page.text('DRAWING STATUS',c3+2,y+16,4.5,true,'#52615d');page.text(status,c3+2,y+22,5.7,true);page.text('SHEET',c4+2,y+16,4.5,true,'#52615d');page.text(`${pageNo}/${total}`,c4+2,y+22,6.0,true);page.text('CREATED USING SAMI - JW EDS',x+w-51,y+h-3,4.6,true,'#0d4038');}
function drawLegend(page,legend,x,y,w,h){page.rect(x,y,w,h,'#5b6864',null,.25);page.text('LEGEND / KEY',x+3,y+7,6.2,true,'#1c2926');let yy=y+13,i=0;for(const [name,st] of legend){if(yy>y+h-5||i++>22)break;page.line(x+3,yy-1.6,x+12,yy-1.6,st.color||'#333',.9,st.type==='service'?[1.5,1]:null);page.wrapped(name,x+15,yy,w-18,5.1,false,'#303a38',2.8,2);yy+=6;}if(!legend.size)page.text('No exported layers',x+3,y+16,5.5,false,'#666');}
function routeBounds(route){return mergeBounds([route?.geometry?.length?boundsOfGeom({coordinates:route.geometry}):null,route?.start?[...route.start,...route.start]:null,route?.end?[...route.end,...route.end]:null]);}
function routeFinalBounds(route){if(!route?.end)return null;const pts=(route.geometry||[]).slice(-Math.min(80,(route.geometry||[]).length));let b=mergeBounds([boundsOfGeom({coordinates:pts}),[route.end[0],route.end[1],route.end[0],route.end[1]]]);return expandBounds(b||[route.end[0],route.end[1],route.end[0],route.end[1]],600);}
