function drawQR(page,text,x,y,size){const mat=qrMatrix(text);page.rect(x,y,size,size,'#111','#fff',.2);if(!mat)return page.text('QR unavailable',x+3,y+size/2,5.5,true,'#b00');const quiet=4,n=mat.length+quiet*2,s=size/n;page.fill('#000');for(let r=0;r<mat.length;r++)for(let c=0;c<mat[r].length;c++)if(mat[r][c])page.rect(x+(c+quiet)*s,y+(r+quiet)*s,s+.02,s+.02,'#000','#000',0);}
function tileXY(lon,lat,z){const n=2**z,x=(lon+180)/360*n,y=(1-Math.log(Math.tan(lat*Math.PI/180)+1/Math.cos(lat*Math.PI/180))/Math.PI)/2*n;return[x,y];}
function tileLL(x,y,z){const n=2**z,lon=x/n*360-180,lat=Math.atan(Math.sinh(Math.PI*(1-2*y/n)))*180/Math.PI;return[lon,lat];}
