async function fetchMapJPEG(bounds,style,wPx=1600,hPx=1000){if(style==='cad'||!bounds)return null;try{const span=tileXY(bounds[2],bounds[1],0)[0]-tileXY(bounds[0],bounds[3],0)[0];let z=18;for(let zz=3;zz<=18;zz++){const a=tileXY(bounds[0],bounds[3],zz),b=tileXY(bounds[2],bounds[1],zz);if(Math.max((b[0]-a[0])*256/wPx,(b[1]-a[1])*256/hPx)>.9){z=Math.max(3,zz-1);break;}}const a=tileXY(bounds[0],bounds[3],z),b=tileXY(bounds[2],bounds[1],z),x0=Math.floor(a[0]),y0=Math.floor(a[1]),x1=Math.floor(b[0]),y1=Math.floor(b[1]);if((x1-x0+1)*(y1-y0+1)>20)return null;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),full=document.createElement('canvas'),fw=(x1-x0+1)*256,fh=(y1-y0+1)*256;full.width=fw;full.height=fh;const fctx=full.getContext('2d');let successfulTiles=0;fctx.fillStyle='#f3f6f0';fctx.fillRect(0,0,fw,fh);for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){const url=style==='satellite'?`https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/${z}/${y}/${x}`:`https://tile.openstreetmap.org/${z}/${x}/${y}.png`;const r=await fetch(url,{mode:'cors',signal:AbortSignal.timeout(9000)});if(!r.ok)continue;const im=await imageFromBlob(await r.blob());fctx.drawImage(im,(x-x0)*256,(y-y0)*256,256,256);successfulTiles++;}if(!successfulTiles)return null;const px0=(a[0]-x0)*256,py0=(a[1]-y0)*256,px1=(b[0]-x0)*256,py1=(b[1]-y0)*256;canvas.width=wPx;canvas.height=hPx;ctx.drawImage(full,px0,py0,Math.max(1,px1-px0),Math.max(1,py1-py0),0,0,wPx,hPx);const data=canvas.toDataURL('image/jpeg',style==='satellite'?.88:.82);return{bytes:dataUrlBytes(data),width:wPx,height:hPx};}catch(e){console.warn('SAMI PDF background unavailable',e);return null;}}
