async function generate(project,opt={}){if(!project)throw Error('No SAMI project supplied.');const paper=opt.paper==='a4'?[297,210]:[420,297],pdf=new PDF(paper[0],paper[1],420,297),pages=[];if(opt.pages?.site!==false)pages.push('site');if(opt.pages?.route!==false)pages.push('route');if(!pages.length)throw Error('Select at least one document page.');let n=1;for(const type of pages){if(type==='site')await renderSitePage(pdf,project,opt,n,pages.length);else await renderRoutePage(pdf,project,opt,n,pages.length);n++;}return pdf.build();}
