 if((m.type==='asset'||m.type==='logo')&&f.geometry.type==='Polygon'){const image=opt._images?.get(m.imageData||project.logos?.find(l=>l.id===m.logoId)?.data);if(image)rotatedImage(page,image,f,tr);else drawVectorAsset(page,f,tr);if(m.ohlNodeKey){const b=boundsOfGeom(f.geometry),pt=tr.point([(b[0]+b[2])/2,(b[1]+b[3])/2]);page.text([m.assetRef,m.voltage?(Number(m.voltage)?Number(m.voltage)/1000+' kV':m.voltage):''].filter(Boolean).join(' / '),pt[0]+2,pt[1]-1,5.2,false,'#7d2966');}if(m.includeLegend!==false)legend.set(legendName(m),{color:st.stroke,type:m.type});continue;}
 for(const ring of flattenLines(f.geometry)){const pts=ring.map(tr.point);if(pts.length<2)continue;page.poly(pts,m.outlineEnabled===false?null:st.stroke,f.geometry.type.includes('Polygon')&&m.fillEnabled!==false?st.fill:null,m.type==='panel'?.12:st.width,st.dash);}
