const generateStudio=generate;
generate=async function(project,opt={}){const options={...opt,_images:new Map()};const data=new Set([...(project.logos||[]).map(l=>l.data),...(project.features||[]).map(f=>f.properties.imageData).filter(Boolean)]);for(const d of data){const im=await preparedImage(d);if(im)options._images.set(d,im);}return generateStudio(project,options);};
fetchMapJPEG=async function(bounds,style,wPx=1600,hPx=1000){if(style==='cad'||!bounds)return null;try{let z=18;for(let zz=3;zz<=18;zz++){const a=tileXY(bounds[0],bounds[3],zz),b=tileXY(bounds[2],bounds[1],zz);if(Math.max((b[0]-a[0])*256/wPx,(b[1]-a[1])*256/hPx)>1){z=Math.max(3,zz-1);break;}}let a,b,x0,x1,y0,y1;const extents=()=>{a=tileXY(bounds[0],bounds[3],z);b=tileXY(bounds[2],bounds[1],z);x0=Math.floor(a[0]);x1=Math.floor(b[0]);y0=Math.floor(a[1]);y1=Math.floor(b[1]);};extents();while((x1-x0+1)*(y1-y0+1)>24&&z>1){z--;extents();}const full=document.createElement('canvas');full.width=(x1-x0+1)*256;full.height=(y1-y0+1)*256;const fctx=full.getContext('2d');fctx.fillStyle='#edf1ea';fctx.fillRect(0,0,full.width,full.height);let next=0,success=0;const jobs=[];for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++)jobs.push([x,y]);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{await Promise.all(Array.from({length:Math.min(4,jobs.length)},async()=>{while(next<jobs.length&&!controller.signal.aborted){const [x,y]=jobs[next++],n=2**z,wrapX=((x%n)+n)%n;try{const url=style==='satellite'?`https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/${z}/${y}/${wrapX}`:`https://tile.openstreetmap.org/${z}/${wrapX}/${y}.png`,r=await fetch(url,{mode:'cors',signal:controller.signal});if(!r.ok)continue;const im=await imageFromBlob(await r.blob());fctx.drawImage(im,(x-x0)*256,(y-y0)*256,256,256);im.close?.();success++;}catch{}}}));}finally{clearTimeout(timer);}if(!success)return null;const canvas=document.createElement('canvas');canvas.width=wPx;canvas.height=hPx;canvas.getContext('2d').drawImage(full,(a[0]-x0)*256,(a[1]-y0)*256,Math.max(1,(b[0]-a[0])*256),Math.max(1,(b[1]-a[1])*256),0,0,wPx,hPx);return{bytes:dataUrlBytes(canvas.toDataURL('image/jpeg',.87)),width:wPx,height:hPx,partial:success<jobs.length};}catch{return null;}};
const originalWrap=wrap;
wrap=function(text,maxMm,size){const limit=Math.max(3,Math.floor(maxMm*PT/(size*.53))),split=ascii(text).split(/\s+/).map(w=>w.length>limit?w.match(new RegExp('.{1,'+limit+'}','g')).join(' '):w).join(' ');return originalWrap(split,maxMm,size);};
