 const m=project.meta||{},metadata=[m.siteAddress,m.clientName,m.siteRef,m.what3words||m.w3w].filter(Boolean);let sideY=metadata.length?31+7+metadata.reduce((n,v)=>n+8+Math.min(4,wrap(v,85,6.8).length)*3.5,0):31;sideY+=11;let keyClipped=false;for(const name of names){if(sideY>166)keyClipped=true;sideY+=Math.min(2,wrap(name,75,6.2).length)*3.5+3;}if(opt.pages?.site!==false&&(keyClipped||gates.length>2||notes.length>350||metadata.some(v=>String(v).length>150))){rows.push(['SITE PLAN DETAILS','']);if(names.length)rows.push(['DRAWING KEY',names.join('\n')]);for(const f of gates)rows.push(['ACCESS POINT: '+f.properties.label,[f.properties.address,f.properties.what3words,`${f.geometry.coordinates[1].toFixed(6)}, ${f.geometry.coordinates[0].toFixed(6)}`,f.properties.arrivalInstructions].filter(Boolean).join('\n')]);for(const [label,value] of [['Site address',m.siteAddress],['Client',m.clientName],['Reference',m.siteRef],['what3words',m.what3words||m.w3w]])if(value)rows.push([label.toUpperCase(),value]);if(notes)rows.push(['DRAWING NOTES',notes]);}
 if(opt.pages?.route!==false&&r&&(routeNotes.join(' ').length>250||constraints.length>3||constraints.join(' ').length>250||String(r.endLabel||'').length>200)){rows.push(['ROUTE DETAILS','']);if(routeNotes.length)rows.push(['ARRIVAL / DRIVER NOTES',routeNotes.join('\n')]);if(constraints.length)rows.push(['RETURNED ROUTE CONSTRAINTS',constraints.join('\n')]);if(r.endLabel)rows.push(['DESTINATION',r.endLabel]);}
