function paginateDetails(rows){const pages=[[]];let count=0;for(const [title,value]of rows){const lines=String(value||'').split('\n').flatMap(t=>wrap(t,370,9));const chunks=[{text:title,title:true},...lines.map(text=>({text,title:false})),{text:'',title:false}];for(const line of chunks){if(count>=43){pages.push([]);count=0;}pages.at(-1).push(line);count++;}}return pages.filter(p=>p.length);}
