generate=async function(project,opt={}){if(!project)throw Error('No project supplied.');const options={...opt,_images:new Map()},data=new Set([...(project.logos||[]).filter(l=>l.export!==false).map(l=>l.data),...(project.features||[]).filter(f=>activeFeature(f,project,opt)).map(f=>f.properties.imageData).filter(Boolean)]);for(const d of data){const im=await preparedImage(d);if(im)options._images.set(d,im);}const pages=[];if(opt.pages?.site!==false)pages.push('site');if(opt.pages?.route!==false)pages.push('route');if(!pages.length)throw Error('Choose an export sheet.');const details=paginateDetails(detailRows(project,opt)),paper=opt.paper==='a4'?[297,210]:[420,297],pdf=new PDF(...paper,420,297),total=pages.length+details.length;options.hasDetails=details.length>0;let n=1;for(const type of pages){if(type==='site')await renderSitePage(pdf,project,options,n++,total);else await renderRoutePage(pdf,project,options,n++,total);}for(const lines of details)await renderDetailsPage(pdf,project,options,n++,total,lines);return pdf.build();};
